+</head>
+<body>
+  <div id="canvas-container"></div>
+
+  <!-- Top HUD Bar -->
+  <header class="top-bar">
+    <div class="hud-group">
+      <h1 class="brand-title">Gemini 4 Argon</h1>
+      <div class="divider"></div>
+      <div class="telemetry">
+        <span>Speed <strong id="hud-speed">0.0 m/s</strong></span>
+        <span>Time <strong id="hud-time">0.00 s</strong></span>
+        <span>Debris <strong id="hud-debris">0</strong></span>
+      </div>
+    </div>
+
+    <div class="hud-group">
+      <span class="seg-label">Camera</span>
+      <div class="segmented" id="camera-switcher">
+        <button type="button" class="btn active" data-cam="impact">Impact</button>
+        <button type="button" class="btn" data-cam="follow">Follow</button>
+        <button type="button" class="btn" data-cam="top">Top</button>
+        <button type="button" class="btn" data-cam="orbit">Orbit</button>
+      </div>
+      <div class="divider"></div>
+      <button type="button" class="btn btn-action" id="btn-toggle-settings">Settings</button>
+    </div>
+  </header>
+
+  <!-- Settings Panel -->
+  <aside class="settings-panel" id="settings-panel">
+    <div class="settings-header">
+      <span>Simulation Parameters</span>
+      <button type="button" class="btn" id="btn-close-settings" style="padding:2px 6px;">✕</button>
+    </div>
+    <div class="settings-body">
+      <div>
+        <div class="settings-section-title">Vehicle Dynamics &amp; Dimensions</div>
+        <div class="settings-grid">
+          <div class="field">
+            <label for="inp-impactSpeed">Impact Speed <span class="unit">m/s</span></label>
+            <input type="number" id="inp-impactSpeed" min="3" max="60" step="0.5" value="22" />
+          </div>
+          <div class="field">
+            <label for="inp-carMass">Car Mass <span class="unit">kg</span></label>
+            <input type="number" id="inp-carMass" min="300" max="5000" step="25" value="1250" />
+          </div>
+          <div class="field">
+            <label for="inp-carLength">Car Length <span class="unit">m</span></label>
