+          </div>
+          <div class="field">
+            <label for="inp-carWidth">Car Width <span class="unit">m</span></label>
+            <input type="number" id="inp-carWidth" min="1.3" max="2.6" step="0.05" value="1.8" />
+          </div>
+          <div class="field full">
+            <label for="inp-carHeight">Car Height <span class="unit">m</span></label>
+            <input type="number" id="inp-carHeight" min="1.05" max="2.3" step="0.05" value="1.45" />
