+            <input type="number" id="inp-brickWidth" min="0.2" max="1.0" step="0.02" value="0.50" />
+          </div>
+          <div class="field">
+            <label for="inp-brickHeight">Brick Height <span class="unit">m</span></label>
+            <input type="number" id="inp-brickHeight" min="0.1" max="0.6" step="0.02" value="0.24" />
+          </div>
+          <div class="field full">
+            <label for="inp-brickDepth">Brick Depth <span class="unit">m</span></label>
+            <input type="number" id="inp-brickDepth" min="0.1" max="0.6" step="0.02" value="0.20" />
+          </div>
+        </div>
+      </div>
+
+      <div>
+        <div class="settings-section-title">Environment &amp; Contact Physics</div>
+        <div class="settings-grid">
+          <div class="field">
+            <label for="inp-gravity">Gravity <span class="unit">m/s²</span></label>
+            <input type="number" id="inp-gravity" min="1" max="30" step="0.01" value="9.81" />
+          </div>
+          <div class="field">
+            <label for="inp-trackLength">Track Length <span class="unit">m</span></label>
+            <input type="number" id="inp-trackLength" min="20" max="90" step="1" value="40" />
+          </div>
+          <div class="field">
+            <label for="inp-brickFriction">Brick Friction</label>
+            <input type="number" id="inp-brickFriction" min="0.05" max="1.5" step="0.01" value="0.72" />
+          </div>
+          <div class="field">
+            <label for="inp-brickRestitution">Brick Restitution</label>
+            <input type="number" id="inp-brickRestitution" min="0.0" max="0.95" step="0.01" value="0.18" />
+          </div>
+          <div class="field full">
+            <label for="inp-groundFriction">Ground Friction</label>
+            <input type="number" id="inp-groundFriction" min="0.05" max="1.5" step="0.01" value="0.85" />
+          </div>
+        </div>
+      </div>
+    </div>
+    <div class="settings-footer">
+      <button type="button" class="btn btn-action" id="btn-reset-defaults">Reset</button>
+      <button type="button" class="btn btn-primary" id="btn-apply-settings">Apply</button>
+    </div>
+  </aside>
+
+  <!-- Bottom Compact Playback Bar -->
+  <nav class="bottom-bar">
+    <button type="button" class="btn btn-primary" id="btn-play-pause" style="min-width: 82px;">Pause</button>
+    <button type="button" class="btn btn-action" id="btn-replay">Replay</button>
+    <div class="divider"></div>
+    <span class="seg-label">Speed</span>
+    <div class="segmented" id="speed-switcher">
+      <button type="button" class="btn" data-speed="0.25">0.25×</button>
+      <button type="button" class="btn" data-speed="0.5">0.5×</button>
+      <button type="button" class="btn active" data-speed="1">1×</button>
+      <button type="button" class="btn" data-speed="2">2×</button>
+    </div>
+  </nav>
+
+  <script type="module">
+    import * as THREE from 'three';
+    import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
+    import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
+    import * as CANNON from 'cannon-es';
+
+    // =========================================================================
+    // 1. MANDATORY DEFAULT EXPERIMENT VALUES
+    // =========================================================================
+    const MANDATORY_DEFAULTS = Object.freeze({
+      impactSpeed: 22,
+      carMass: 1250,
+      carLength: 4.2,
+      carWidth: 1.8,
+      carHeight: 1.45,
+      wallCols: 12,
+      wallRows: 8,
+      wallDepth: 2,
+      brickMass: 2.5,
+      brickWidth: 0.50,
+      brickHeight: 0.24,
+      brickDepth: 0.20,
+      gravity: 9.81,
+      brickFriction: 0.72,
+      brickRestitution: 0.18,
+      groundFriction: 0.85,
+      trackLength: 40
+    });
+
+    // Collision filter bitmasks (prevents attached car parts from self-colliding prior to detachment)
+    const GROUP_GROUND = 1;
+    const GROUP_BRICK = 2;
+    const GROUP_CAR_ATTACHED = 4;
+    const GROUP_CAR_DETACHED = 8;
+    const GROUP_SHARD = 16;
+
+    // Seeded PRNG for strictly visual textures & particles (never touches physics)
+    function createSeededRandom(seed = 1337) {
+      let s = seed >>> 0;
+      return function () {
+        s = (s + 0x6D2B79F5) >>> 0;
+        let t = Math.imul(s ^ (s >>> 15), 1 | s);
+        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+      };
+    }
+
+    // =========================================================================
+    // 2. RENDERER, SCENE, CAMERAS & LIGHTING SETUP
+    // =========================================================================
+    const container = document.getElementById('canvas-container');
+    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
+    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
+    renderer.setSize(window.innerWidth, window.innerHeight);
+    renderer.shadowMap.enabled = true;
+    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
+    renderer.toneMapping = THREE.ACESFilmicToneMapping;
+    renderer.toneMappingExposure = 1.08;
+    container.appendChild(renderer.domElement);
+
+    const scene = new THREE.Scene();
+    scene.fog = new THREE.FogExp2(0x8fa7c4, 0.0045);
+
+    // Generate procedural IBL environment with RoomEnvironment
+    const pmremGenerator = new THREE.PMREMGenerator(renderer);
+    pmremGenerator.compileEquirectangularShader();
+    const roomEnv = new RoomEnvironment();
+    const envTexture = pmremGenerator.fromScene(roomEnv, 0.04).texture;
+    scene.environment = envTexture;
+    roomEnv.dispose();
+
+    // Sky Dome
+    function createSkyDome() {
+      const skyGeo = new THREE.SphereGeometry(260, 32, 20);
+      const skyMat = new THREE.ShaderMaterial({
+        side: THREE.BackSide,
+        depthWrite: false,
+        uniforms: {
+          topColor: { value: new THREE.Color(0x28568f) },
+          horizonColor: { value: new THREE.Color(0xa6bfd8) },
+          groundColor: { value: new THREE.Color(0x4b5563) },
+          sunDir: { value: new THREE.Vector3(0.45, 0.65, 0.61).normalize() }
+        },
+        vertexShader: `
+          varying vec3 vWorldPos;
+          void main() {
+            vec4 wp = modelMatrix * vec4(position, 1.0);
+            vWorldPos = wp.xyz;
+            gl_Position = projectionMatrix * viewMatrix * wp;
+          }
+        `,
+        fragmentShader: `
+          varying vec3 vWorldPos;
+          uniform vec3 topColor;
+          uniform vec3 horizonColor;
+          uniform vec3 groundColor;
+          uniform vec3 sunDir;
+          void main() {
+            vec3 d = normalize(vWorldPos);
+            float h = d.y;
+            vec3 col = mix(horizonColor, topColor, pow(clamp(h, 0.0, 1.0), 0.55));
+            col = mix(col, groundColor, clamp(-h * 3.0, 0.0, 1.0));
+            float sunAmt = max(dot(d, sunDir), 0.0);
+            col += vec3(1.0, 0.9, 0.7) * pow(sunAmt, 36.0) * 0.45;
+            col += vec3(1.0, 0.96, 0.85) * smoothstep(0.9985, 0.9998, sunAmt) * 2.5;
+            gl_FragColor = vec4(col, 1.0);
+          }
+        `
+      });
+      return new THREE.Mesh(skyGeo, skyMat);
+    }
+    scene.add(createSkyDome());
+
+    // Main Sun Directional Light with tight 2048 PCFSoftShadowMap
+    const sunLight = new THREE.DirectionalLight(0xfff5e4, 3.2);
+    sunLight.position.set(18, 28, 22);
+    sunLight.castShadow = true;
+    sunLight.shadow.mapSize.set(2048, 2048);
+    sunLight.shadow.camera.near = 4;
+    sunLight.shadow.camera.far = 90;
+    sunLight.shadow.camera.left = -28;
+    sunLight.shadow.camera.right = 24;
+    sunLight.shadow.camera.top = 14;
+    sunLight.shadow.camera.bottom = -14;
+    sunLight.shadow.bias = -0.00035;
+    sunLight.shadow.normalBias = 0.014;
+    scene.add(sunLight);
+    scene.add(sunLight.target);
+
+    const hemiLight = new THREE.HemisphereLight(0xb8d4ff, 0x3b3834, 0.55);
+    scene.add(hemiLight);
+
+    // Camera and OrbitControls
+    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.15, 450);
+    const orbitControls = new OrbitControls(camera, renderer.domElement);
+    orbitControls.enableDamping = true;
+    orbitControls.dampingFactor = 0.07;
+    orbitControls.maxPolarAngle = Math.PI * 0.49;
+    orbitControls.minDistance = 2.0;
+    orbitControls.maxDistance = 90.0;
+    orbitControls.enabled = false;
+
+    // =========================================================================
+    // 3. PROCEDURAL PBR TEXTURES & SHARED MATERIALS
+    // =========================================================================
+    function createAsphaltTextures() {
+      const rng = createSeededRandom(404);
+      const size = 512;
+      const canvas = document.createElement('canvas');
