+    // =========================================================================
+    // 6. FREESTANDING RUNNING-BOND BRICK WALL BUILDER
+    // =========================================================================
+    function buildBrickWall(cfg, brickPhysMat) {
+      brickEntities = [];
+      const cols = Math.max(2, Math.round(cfg.wallCols));
+      const rows = Math.max(2, Math.round(cfg.wallRows));
+      const depth = Math.max(1, Math.round(cfg.wallDepth));
+
+      const bW = cfg.brickWidth;  // width across track (Z)
+      const bH = cfg.brickHeight; // height (Y)
+      const bD = cfg.brickDepth;  // depth along track (X)
+      const bMass = cfg.brickMass;
+
+      // Visible mortar gaps: slightly smaller visual brick shell around mortar core
+      const mortarGap = Math.min(0.012, Math.min(bW, bH, bD) * 0.06);
+      const outerGeo = new THREE.BoxGeometry(bD - mortarGap, bH - mortarGap, bW - mortarGap);
+      const mortarGeo = new THREE.BoxGeometry(bD - mortarGap * 0.25, bH, bW - mortarGap * 0.25);
+
+      // Physics half-extents: exact vertical stacking, tiny 3mm horizontal gap to prevent pre-impact side stress
+      const physGapXZ = 0.003;
+      const shape = new CANNON.Box(new CANNON.Vec3(bD * 0.5, bH * 0.5, bW * 0.5));
+
+      const stepX = bD + physGapXZ;
+      const stepZ = bW + physGapXZ;
+
+      const grid = new Map();
+      const key = (r, c, d) => `${r}:${c}:${d}`;
+
+      for (let d = 0; d < depth; d++) {
+        const x = wallX + (d - (depth - 1) * 0.5) * stepX;
+        for (let r = 0; r < rows; r++) {
+          const y = (r + 0.5) * bH;
+          // Staggered running bond on odd rows, plus subtle layer offset
+          const staggerZ = ((r % 2 === 1) ? 0.5 : 0.0) * stepZ - 0.25 * stepZ;
+
+          for (let c = 0; c < cols; c++) {
+            const z = (c - (cols - 1) * 0.5) * stepZ + staggerZ;
+
+            const body = new CANNON.Body({
+              mass: bMass,
+              material: brickPhysMat,
+              linearDamping: 0.04,
+              angularDamping: 0.08,
+              collisionFilterGroup: GROUP_BRICK,
+              collisionFilterMask: GROUP_GROUND | GROUP_BRICK | GROUP_CAR_ATTACHED | GROUP_CAR_DETACHED | GROUP_SHARD
+            });
+            body.addShape(shape);
+            body.position.set(x, y, z);
+            body.prevPos = body.position.clone();
+            body.prevQuat = body.quaternion.clone();
+            world.addBody(body);
+
+            const matIdx = (r * 17 + c * 31 + d * 13) % MATERIALS.brickVariants.length;
+            const meshGroup = new THREE.Group();
+            const brickMesh = new THREE.Mesh(outerGeo, MATERIALS.brickVariants[matIdx]);
+            brickMesh.castShadow = true;
+            brickMesh.receiveShadow = true;
+            meshGroup.add(brickMesh);
+
+            const mortarMesh = new THREE.Mesh(mortarGeo, MATERIALS.mortar);
+            mortarMesh.receiveShadow = true;
+            meshGroup.add(mortarMesh);
+
+            meshGroup.position.copy(body.position);
+            simGroup.add(meshGroup);
+
+            // Structural mortar bond health scaled by brickMass and brickFriction
+            const baseBond = bMass * (1.8 + cfg.brickFriction * 2.5) * (r === 0 ? 1.5 : 1.0);
+            const entity = {
+              body,
+              mesh: meshGroup,
+              row: r,
+              col: c,
+              layer: d,
+              halfH: bH * 0.5,
+              footprintX: bD * 1.35,
+              footprintZ: bW * 1.35,
+              restPos: new CANNON.Vec3(x, y, z),
+              mortarIntact: true,
+              mortarHealth: baseBond,
+              neighbors: [],
+              lowerSupports: []
+            };
+
+            brickEntities.push(entity);
+            allPhysicsEntries.push(entity);
+            grid.set(key(r, c, d), entity);
+          }
+        }
+      }
