+      // Wire running-bond neighbor & lower-support references for masonry crack propagation
+      for (const b of brickEntities) {
+        const { row: r, col: c, layer: d } = b;
+        const candidates = [
+          grid.get(key(r, c - 1, d)),
+          grid.get(key(r, c + 1, d)),
+          grid.get(key(r - 1, c, d)),
+          grid.get(key(r + 1, c, d)),
+          grid.get(key(r, c, d - 1)),
+          grid.get(key(r, c, d + 1)),
+          grid.get(key(r - 1, c + (r % 2 === 1 ? 1 : -1), d)),
+          grid.get(key(r + 1, c + (r % 2 === 1 ? 1 : -1), d))
+        ];
+        for (const nb of candidates) {
+          if (nb) {
+            b.neighbors.push(nb);
+            if (nb.row === r - 1 && nb.layer === d) {
+              b.lowerSupports.push(nb);
+            }
+          }
+        }
+      }
