+    // =========================================================================
+    // 8. CONTACT SHADOWS & VISUAL FX (DUST, SPARKS, SKID MARKS)
+    // =========================================================================
+    function buildContactShadowsAndFX() {
+      // Single InstancedMesh for all ground contact shadows (1 draw call!)
+      contactShadowTargets = [...allPhysicsEntries];
+      const count = contactShadowTargets.length;
+      const quadGeo = new THREE.PlaneGeometry(1, 1);
+      quadGeo.rotateX(-Math.PI / 2);
+      contactShadowMesh = new THREE.InstancedMesh(quadGeo, MATERIALS.contactShadow, count);
+      contactShadowMesh.renderOrder = 1;
+      simGroup.add(contactShadowMesh);
+
+      // Skid marks InstancedMesh
+      const skidGeo = new THREE.PlaneGeometry(0.46, 0.24);
+      skidGeo.rotateX(-Math.PI / 2);
+      skidMesh = new THREE.InstancedMesh(skidGeo, MATERIALS.skidMark, MAX_SKIDS);
+      skidMesh.count = 0;
+      skidMesh.renderOrder = 2;
+      simGroup.add(skidMesh);
+      skidCount = 0;
+
+      // Dust & Sparks pools
+      dustParticles = [];
+      sparkParticles = [];
+      const dustGeo = new THREE.DodecahedronGeometry(0.24, 1);
+      const dustMat = new THREE.MeshLambertMaterial({
+        color: 0xcbbfb0,
+        transparent: true,
+        opacity: 0.42,
+        depthWrite: false
+      });
+
+      for (let i = 0; i < 42; i++) {
+        const m = new THREE.Mesh(dustGeo, dustMat.clone());
+        m.visible = false;
+        simGroup.add(m);
+        dustParticles.push({ mesh: m, active: false, age: 0, life: 1, vel: new THREE.Vector3(), scale: 1 });
+      }
+
+      const sparkGeo = new THREE.BoxGeometry(0.26, 0.032, 0.032);
+      const sparkMat = new THREE.MeshBasicMaterial({ color: 0xffb703 });
+      for (let i = 0; i < 56; i++) {
+        const m = new THREE.Mesh(sparkGeo, sparkMat);
+        m.visible = false;
+        simGroup.add(m);
+        sparkParticles.push({ mesh: m, active: false, age: 0, life: 0.4, vel: new THREE.Vector3() });
+      }
+    }
+
+    function spawnDust(pos, speedScale = 1) {
+      const slot = dustParticles.find((p) => !p.active);
+      if (!slot) return;
+      slot.active = true;
+      slot.age = 0;
+      slot.life = 0.65 + fxRng() * 0.75;
+      slot.scale = 0.6 + fxRng() * 0.9;
+      slot.mesh.position.set(
+        pos.x + (fxRng() - 0.5) * 0.5,
+        Math.max(0.15, pos.y + (fxRng() - 0.5) * 0.4),
+        pos.z + (fxRng() - 0.5) * 0.5
+      );
+      slot.vel.set(
+        (fxRng() - 0.3) * 3.5 * speedScale,
+        1.2 + fxRng() * 2.4,
+        (fxRng() - 0.5) * 3.5 * speedScale
+      );
+      slot.mesh.visible = true;
+    }
+
+    function spawnSpark(pos, baseVx) {
+      const slot = sparkParticles.find((p) => !p.active);
+      if (!slot) return;
+      slot.active = true;
+      slot.age = 0;
+      slot.life = 0.25 + fxRng() * 0.35;
+      slot.mesh.position.set(
+        pos.x + (fxRng() - 0.5) * 0.4,
+        Math.max(0.08, pos.y + (fxRng() - 0.5) * 0.3),
+        pos.z + (fxRng() - 0.5) * 0.4
