+    // =========================================================================
+    // 9. PHYSICS STEPPING, MASONRY FRACTURE & PROGRESSIVE CAR DESTRUCTION
+    // =========================================================================
+    function stepPhysics(dt) {
+      if (!world || !carState) return;
+
+      // Save previous transforms for smooth slow-motion interpolation
+      for (let i = 0; i < allPhysicsEntries.length; i++) {
+        const b = allPhysicsEntries[i].body;
+        b.prevPos.copy(b.position);
+        b.prevQuat.copy(b.quaternion);
+      }
+
+      const cfg = activeSettings;
+      const chassis = carState.parts.chassis.body;
+      const frontBumper = carState.parts.frontBumper.body;
+      const frontClip = carState.parts.frontClip.body;
+      const engineBay = carState.parts.engineBay.body;
+
+      const wallFrontX = wallX - (cfg.wallDepth * cfg.brickDepth) * 0.5;
+      const noseX = frontBumper.position.x + cfg.carLength * 0.035;
+
+      // A. Pre-impact uniform vehicle acceleration to reach exact target impactSpeed at wall
+      if (!hasImpacted) {
+        if (noseX >= wallFrontX - 0.08) {
+          hasImpacted = true;
+          impactTime = simTime;
+          cameraShakeTrauma = Math.min(1.0, cfg.impactSpeed / 25);
+        } else {
+          const distRemaining = Math.max(0.35, wallFrontX - noseX);
+          const curVx = chassis.velocity.x;
+          const targetV = cfg.impactSpeed;
+          const reqAccel = (targetV * targetV - curVx * curVx) / (2 * distRemaining);
+
+          for (const key in carState.parts) {
+            const p = carState.parts[key];
+            if (!p.detached) {
+              p.body.force.x += p.body.mass * reqAccel;
+              p.body.velocity.z *= 0.92;
+              p.body.angularVelocity.x *= 0.9;
+              p.body.angularVelocity.y *= 0.9;
+            }
+          }
+
+          // Spin attached wheels visually
+          carState.wheelAngle -= (curVx * dt) / (cfg.carHeight * 0.235);
+          for (const wName of ['wheelFL', 'wheelFR', 'wheelRL', 'wheelRR']) {
+            const wp = carState.parts[wName];
+            if (!wp.detached) {
+              wp.body.quaternion.setFromAxisAngle(new CANNON.Vec3(0, 0, 1), carState.wheelAngle);
+            }
+          }
+        }
+      }
+
+      // Step rigid-body solver
+      world.step(dt);
+      simTime += dt;
+
+      // B. Masonry Mortar Cohesion, Fracture Propagation & Momentum Transfer
+      const carFrontX = Math.max(frontClip.position.x, engineBay.position.x + cfg.carLength * 0.12);
+      const carZ = chassis.position.z;
+      const carHalfW = cfg.carWidth * 0.52;
+      const carTopY = cfg.carHeight * 1.05;
+
+      let stepImpactImpulse = 0;
+
+      for (let i = 0; i < brickEntities.length; i++) {
+        const b = brickEntities[i];
+        const body = b.body;
+
+        if (b.mortarIntact) {
+          const dx = body.position.x - b.restPos.x;
+          const dy = body.position.y - b.restPos.y;
+          const dz = body.position.z - b.restPos.z;
+          const dispSq = dx * dx + dy * dy + dz * dz;
+          const speedSq = body.velocity.lengthSquared();
+
+          // Check if car front is striking this brick directly
+          const inCarZone =
+            hasImpacted &&
+            Math.abs(body.position.x - carFrontX) < cfg.brickDepth * 1.35 + cfg.carLength * 0.16 &&
+            Math.abs(body.position.z - carZ) < carHalfW + cfg.brickWidth * 0.35 &&
+            body.position.y < carTopY;
+
+          if (inCarZone && chassis.velocity.x > 1.2) {
+            const relV = Math.max(0, chassis.velocity.x - body.velocity.x);
+            const directImpulse = relV * b.body.mass * (1.85 + cfg.brickFriction * 1.15);
+            b.mortarHealth -= directImpulse;
+            stepImpactImpulse += directImpulse;
+
+            if (b.mortarHealth <= 0) {
+              b.mortarIntact = false;
+              const zOff = body.position.z - carZ;
+              const yRatio = Math.min(1, body.position.y / cfg.carHeight);
+              body.velocity.x += relV * (0.72 + yRatio * 0.32);
+              body.velocity.y += (1.6 + yRatio * 4.2) * (relV / 18);
+              body.velocity.z += zOff * (2.4 + yRatio * 1.5) * (relV / 18);
+              body.angularVelocity.set(
+                (b.row % 2 === 0 ? 1 : -1) * 4.5,
+                zOff * 3.8,
+                -relV * 0.35
+              );
