+              // Equal & opposite reaction impulse onto the car structure
+              const reaction = directImpulse * 1.28;
+              const fShare = reaction / cfg.carMass;
+              chassis.velocity.x = Math.max(0, chassis.velocity.x - fShare * 0.72);
+              engineBay.velocity.x = Math.max(0, engineBay.velocity.x - fShare * 0.85);
+              frontClip.velocity.x = Math.max(0, frontClip.velocity.x - fShare * 1.05);
+
+              // Propagate fracture stress to immediate masonry neighbors
+              for (let n = 0; n < b.neighbors.length; n++) {
+                b.neighbors[n].mortarHealth -= directImpulse * 0.42;
+              }
