+              b.mortarIntact = false;
+            } else {
+              // Intact masonry holds position cleanly prior to fracture
+              body.position.copy(b.restPos);
+              body.velocity.set(0, 0, 0);
+              body.angularVelocity.set(0, 0, 0);
+            }
+          } else if (b.lowerSupports.length > 0 && b.lowerSupports.every((s) => !s.mortarIntact)) {
+            b.mortarIntact = false;
+          }
+        }
+      }
+
+      // Also measure solver contact multipliers between car bodies and bricks
+      for (let i = 0; i < world.contacts.length; i++) {
+        const c = world.contacts[i];
+        const gA = c.bi.collisionFilterGroup;
+        const gB = c.bj.collisionFilterGroup;
+        if (
+          (gA === GROUP_BRICK && (gB === GROUP_CAR_ATTACHED || gB === GROUP_CAR_DETACHED)) ||
+          (gB === GROUP_BRICK && (gA === GROUP_CAR_ATTACHED || gA === GROUP_CAR_DETACHED))
+        ) {
+          if (!hasImpacted) {
+            hasImpacted = true;
+            impactTime = simTime;
+            cameraShakeTrauma = Math.min(1.0, cfg.impactSpeed / 25);
+          }
+          stepImpactImpulse += Math.min(450, Math.abs(c.multiplier || 0) * dt * 18 + 14);
+        }
+      }
+
+      // C. Progressive Car Breakup, Front Clip Crumple & Undercarriage Braking
+      if (hasImpacted) {
+        carState.accumulatedImpulse += stepImpactImpulse;
+        const normImpulse = carState.accumulatedImpulse / carState.referenceImpulse;
+
+        // 1. Check breakable constraints against their physical impulse thresholds
+        for (let i = 0; i < carState.constraints.length; i++) {
+          const item = carState.constraints[i];
+          if (!item.broken && normImpulse >= item.thresholdRatio) {
+            item.broken = true;
+            world.removeConstraint(item.constraint);
+            if (item.breakAction) item.breakAction();
+          }
+        }
+
+        // 2. Permanent Front Clip Plastic Crumple (shortens nose backward & tilts upward)
+        const targetCrumple = Math.min(carState.maxCrumple, normImpulse * carState.maxCrumple * 1.35);
+        if (targetCrumple > carState.crumpleAmount) {
+          const deltaC = targetCrumple - carState.crumpleAmount;
+          carState.crumpleAmount = targetCrumple;
+
+          for (let j = 0; j < carState.crumpleJoints.length; j++) {
+            const cj = carState.crumpleJoints[j];
+            if (!cj.broken) {
+              cj.pivotA.x -= deltaC;
+              cj.pivotA.y += deltaC * (j === 1 ? 0.34 : 0.14);
+            }
+          }
+          for (let j = 0; j < carState.firewallJoints.length; j++) {
+            const fj = carState.firewallJoints[j];
+            if (!fj.broken) {
+              fj.pivotA.x -= deltaC * 0.25;
+            }
+          }
+        }
+
+        // 3. Deform Hood vertices into a visible V-buckle crease
+        const targetBuckle = Math.min(0.28, normImpulse * 0.36);
+        if (targetBuckle > carState.hoodBuckle + 0.005) {
+          carState.hoodBuckle = targetBuckle;
+          const hoodEntry = carState.parts.hood;
+          for (const geo of hoodEntry.deformGeos) {
+            const posAttr = geo.attributes.position;
+            for (let v = 0; v < posAttr.count; v++) {
+              const vx = posAttr.getX(v);
+              const normalizedX = 1.0 - Math.min(1.0, Math.abs(vx) / (cfg.carLength * 0.155));
+              const signY = posAttr.getY(v) >= 0 ? 1 : -1;
+              posAttr.setY(v, signY * cfg.carHeight * 0.02 + Math.pow(normalizedX, 1.5) * carState.hoodBuckle);
+            }
+            posAttr.needsUpdate = true;
+            geo.computeVertexNormals();
+          }
+        }
+
+        // 4. Post-impact damaged undercarriage & locked-wheel asphalt friction
+        const damageFactor = Math.min(1.0, normImpulse * 1.15);
+        if (damageFactor > 0.12 && chassis.position.y < cfg.carHeight * 0.65) {
+          const brakeDecel = cfg.groundFriction * cfg.gravity * (0.65 + damageFactor * 0.95);
+          const dv = brakeDecel * dt;
+
+          for (const key in carState.parts) {
+            const p = carState.parts[key];
+            if (!p.detached) {
+              const vx = p.body.velocity.x;
+              if (Math.abs(vx) > 0.05) {
+                p.body.velocity.x -= Math.sign(vx) * Math.min(Math.abs(vx), dv);
+              }
+              p.body.velocity.z *= 0.985;
+              p.body.angularVelocity.scale(0.96, p.body.angularVelocity);
+            }
+          }
+
+          // Emit tire skid marks & scraping sparks while wreck skids to a stop
+          if (chassis.velocity.lengthSquared() > 2.2) {
+            const stepTick = Math.round(simTime / dt);
+            if (stepTick % 4 === 0) {
+              for (const wName of ['wheelFL', 'wheelFR', 'wheelRL', 'wheelRR']) {
+                const wp = carState.parts[wName];
+                if (!wp.detached && wp.body.position.y < wp.wheelR * 1.35) {
+                  addSkidMark(wp.body.position.x, wp.body.position.z);
+                }
+              }
+            }
+            if (stepTick % 3 === 0 && damageFactor > 0.35) {
+              spawnSpark(frontClip.position, chassis.velocity.x);
+            }
+          }
+        }
+
+        // Spin any remaining attached wheels at damped rate
+        carState.wheelAngle -= (chassis.velocity.x * dt * (1 - damageFactor * 0.85)) / (cfg.carHeight * 0.235);
+        for (const wName of ['wheelFL', 'wheelFR', 'wheelRL', 'wheelRR']) {
+          const wp = carState.parts[wName];
+          if (!wp.detached) {
+            wp.body.quaternion.setFromAxisAngle(new CANNON.Vec3(0, 0, 1), carState.wheelAngle);
+          }
+        }
+      }
+
+      // D. Velocity sanity clamp & floor safety
+      const maxVel = Math.max(65, cfg.impactSpeed * 2.1);
+      const maxVelSq = maxVel * maxVel;
+      for (let i = 0; i < allPhysicsEntries.length; i++) {
+        const b = allPhysicsEntries[i].body;
+        const vSq = b.velocity.lengthSquared();
+        if (vSq > maxVelSq) {
+          b.velocity.scale(maxVel / Math.sqrt(vSq), b.velocity);
+        }
+        if (b.position.y < b.shapes[0].boundingSphereRadius * 0.25) {
+          b.position.y = b.shapes[0].boundingSphereRadius * 0.25;
+          if (b.velocity.y < 0) b.velocity.y = 0;
+        }
+      }
+
+      // E. Update visual particles
+      for (let i = 0; i < dustParticles.length; i++) {
+        const p = dustParticles[i];
+        if (!p.active) continue;
+        p.age += dt;
+        if (p.age >= p.life) {
+          p.active = false;
+          p.mesh.visible = false;
+          continue;
+        }
+        const t = p.age / p.life;
+        p.mesh.position.addScaledVector(p.vel, dt);
+        p.vel.multiplyScalar(0.96);
+        const s = p.scale * (1 + t * 2.8);
+        p.mesh.scale.set(s, s * 0.85, s);
+        p.mesh.material.opacity = 0.42 * (1 - t);
+      }
+
+      for (let i = 0; i < sparkParticles.length; i++) {
+        const p = sparkParticles[i];
+        if (!p.active) continue;
+        p.age += dt;
+        if (p.age >= p.life) {
+          p.active = false;
+          p.mesh.visible = false;
+          continue;
+        }
+        p.vel.y -= cfg.gravity * dt;
+        p.mesh.position.addScaledVector(p.vel, dt);
+        if (p.mesh.position.y < 0.03) {
+          p.mesh.position.y = 0.03;
+          p.vel.y = Math.abs(p.vel.y) * 0.45;
+        }
+        p.mesh.lookAt(
+          p.mesh.position.x + p.vel.x,
+          p.mesh.position.y + p.vel.y,
+          p.mesh.position.z + p.vel.z
+        );
+      }
+
+      if (cameraShakeTrauma > 0) {
+        cameraShakeTrauma = Math.max(0, cameraShakeTrauma - dt * 1.75);
+      }
+    }
+
+    // =========================================================================
+    // 10. VISUAL SYNCHRONIZATION & CAMERA CHOREOGRAPHY
+    // =========================================================================
+    const interpPos = new THREE.Vector3();
+    const interpQuat = new THREE.Quaternion();
+    const shadowDummy = new THREE.Object3D();
+    const camTarget = new THREE.Vector3();
+    const camDesiredPos = new THREE.Vector3();
+
+    function syncVisualsAndCameras(alpha) {
+      if (!carState) return;
+
+      // 1. Interpolate rigid-body transforms & update single-draw-call Contact Shadows
+      for (let i = 0; i < allPhysicsEntries.length; i++) {
+        const entry = allPhysicsEntries[i];
+        const b = entry.body;
+
+        interpPos.lerpVectors(b.prevPos, b.position, alpha);
+        interpQuat.slerpQuaternions(b.prevQuat, b.quaternion, alpha);
+
+        entry.mesh.position.copy(interpPos);
+        entry.mesh.quaternion.copy(interpQuat);
+
+        // Contact shadow projection onto ground plane (y = 0.006)
+        const clearance = Math.max(0, interpPos.y - entry.halfH);
+        if (clearance < 1.35) {
+          const fade = Math.max(0.15, 1.0 - clearance / 1.35);
+          shadowDummy.position.set(interpPos.x, 0.006, interpPos.z);
+          shadowDummy.rotation.set(-Math.PI / 2, 0, 0);
+          shadowDummy.scale.set(entry.footprintX * fade, entry.footprintZ * fade, 1);
+        } else {
+          shadowDummy.position.set(0, -10, 0);
+          shadowDummy.scale.set(0.001, 0.001, 0.001);
+        }
+        shadowDummy.updateMatrix();
+        contactShadowMesh.setMatrixAt(i, shadowDummy.matrix);
+      }
+      contactShadowMesh.instanceMatrix.needsUpdate = true;
+
+      // 2. Camera Choreography (Impact, Follow, Top, Orbit)
+      const chassisPos = carState.parts.chassis.mesh.position;
+      const shakeAmt = cameraShakeTrauma * cameraShakeTrauma * 0.22;
+      const shakeX = Math.sin(simTime * 53.0) * shakeAmt;
+      const shakeY = Math.cos(simTime * 67.0) * shakeAmt;
+
+      if (cameraMode === 'impact') {
+        orbitControls.enabled = false;
+        // Three-quarter cinematic shot keeping car, track, and collapsing wall framed
+        const focusX = hasImpacted
+          ? THREE.MathUtils.clamp((wallX * 0.45 + chassisPos.x * 0.55), wallX - 2.0, wallX + 5.5)
+          : (chassisPos.x * 0.35 + wallX * 0.65);
+
+        const wallSpan = Math.max(6.0, activeSettings.wallCols * activeSettings.brickWidth);
+        const distZ = Math.max(8.8, wallSpan * 1.15);
+
+        camDesiredPos.set(wallX + 6.2 + shakeX, 2.55 + shakeY, distZ);
+        camTarget.set(focusX, 1.05 + shakeY * 0.5, 0);
+
+        camera.position.lerp(camDesiredPos, 0.12);
+        camera.up.set(0, 1, 0);
+        camera.lookAt(camTarget);
+      } else if (cameraMode === 'follow') {
+        orbitControls.enabled = false;
+        const leadX = Math.min(chassisPos.x, wallX + 6.5);
+        camDesiredPos.set(leadX - 7.8 + shakeX, 2.75 + shakeY, 2.6);
+        camTarget.set( (leadX + wallX) * 0.5 + 1.5, 1.1 + shakeY * 0.5, 0 );
+
+        camera.position.lerp(camDesiredPos, 0.16);
+        camera.up.set(0, 1, 0);
+        camera.lookAt(camTarget);
+      } else if (cameraMode === 'top') {
+        orbitControls.enabled = false;
+        const centerFocusX = THREE.MathUtils.clamp((chassisPos.x * 0.4 + wallX * 0.6), wallX - 10, wallX + 4);
+        camera.position.set(centerFocusX, 24.5, 0.01);
+        camera.up.set(0, 0, -1);
+        camera.lookAt(centerFocusX, 0, 0);
+      } else if (cameraMode === 'orbit') {
+        orbitControls.enabled = true;
+        camera.up.set(0, 1, 0);
+        if (!orbitUserInteracted) {
+          orbitControls.target.set(wallX - 0.5, 1.1, 0);
+        }
+        orbitControls.update();
+      }
+
+      // 3. Update Live Telemetry HUD
+      const speedMs = carState.parts.chassis.body.velocity.length();
+      document.getElementById('hud-speed').textContent = `${speedMs.toFixed(1)} m/s`;
+      document.getElementById('hud-time').textContent = `${simTime.toFixed(2)} s`;
+
+      let brokenCount = 0;
+      for (const k in carState.parts) {
+        if (carState.parts[k].detached) brokenCount++;
+      }
+      for (let i = 0; i < brickEntities.length; i++) {
+        if (!brickEntities[i].mortarIntact) brokenCount++;
+      }
+      document.getElementById('hud-debris').textContent = String(brokenCount);
+    }
+
+    // =========================================================================
+    // 11. SIMULATION REBUILD & DETERMINISTIC INITIALIZATION
+    // =========================================================================
+    function clearSimGroup() {
+      while (simGroup.children.length > 0) {
+        const child = simGroup.children[0];
+        simGroup.remove(child);
+      }
+    }
+
+    function rebuildSimulation() {
+      clearSimGroup();
+      allPhysicsEntries = [];
+      brickEntities = [];
+      contactShadowTargets = [];
+
+      simTime = 0;
+      simAccumulator = 0;
+      hasImpacted = false;
+      impactTime = -1;
+      cameraShakeTrauma = 0;
+      fxRng = createSeededRandom(777);
+
+      const cfg = activeSettings;
+
+      // Initialize fresh deterministic Cannon-es world
+      world = new CANNON.World();
+      world.gravity.set(0, -cfg.gravity, 0);
+      world.broadphase = new CANNON.SAPBroadphase(world);
+      world.solver.iterations = 12;
+      world.solver.tolerance = 0.0005;
+
+      const groundMat = new CANNON.Material('ground');
+      const brickMat = new CANNON.Material('brick');
+      const carMat = new CANNON.Material('car');
+      const wheelMat = new CANNON.Material('wheel');
+
+      world.addContactMaterial(new CANNON.ContactMaterial(groundMat, brickMat, {
+        friction: Math.sqrt(cfg.groundFriction * cfg.brickFriction),
+        restitution: cfg.brickRestitution * 0.6
+      }));
+      world.addContactMaterial(new CANNON.ContactMaterial(brickMat, brickMat, {
+        friction: cfg.brickFriction,
+        restitution: cfg.brickRestitution
+      }));
+      world.addContactMaterial(new CANNON.ContactMaterial(carMat, brickMat, {
+        friction: cfg.brickFriction * 0.65,
+        restitution: cfg.brickRestitution
+      }));
+      world.addContactMaterial(new CANNON.ContactMaterial(groundMat, carMat, {
+        friction: 0.0, // Attached runner skids are frictionless; post-impact braking is applied explicitly
+        restitution: 0.08
+      }));
+      world.addContactMaterial(new CANNON.ContactMaterial(groundMat, wheelMat, {
+        friction: cfg.groundFriction * 0.55,
+        restitution: 0.28
+      }));
+
+      // Static ground plane collider
+      const groundBody = new CANNON.Body({
+        mass: 0,
+        material: groundMat,
+        collisionFilterGroup: GROUP_GROUND,
+        collisionFilterMask: GROUP_BRICK | GROUP_CAR_ATTACHED | GROUP_CAR_DETACHED | GROUP_SHARD
+      });
+      groundBody.addShape(new CANNON.Plane());
+      groundBody.quaternion.setFromAxisAngle(new CANNON.Vec3(1, 0, 0), -Math.PI / 2);
+      world.addBody(groundBody);
+
+      // Build Track, Brick Wall, Car, and Contact Shadows
+      buildTrackAndEnvironment(cfg);
+      buildBrickWall(cfg, brickMat);
+      carState = buildDestructibleCar(cfg, carMat, wheelMat);
+      buildContactShadowsAndFX();
+
+      // Set initial launch velocity on all car parts so the car immediately accelerates down the track
+      const launchSpeed = Math.min(cfg.impactSpeed * 0.42, 9.0);
+      for (const k in carState.parts) {
+        carState.parts[k].body.velocity.set(launchSpeed, 0, 0);
+      }
+
+      // Snap initial camera position for clean framing
+      if (cameraMode === 'impact') {
+        const wallSpan = Math.max(6.0, cfg.wallCols * cfg.brickWidth);
+        camera.position.set(wallX + 6.5, 2.6, Math.max(8.8, wallSpan * 1.15));
+        camera.lookAt(wallX - 3.5, 1.05, 0);
+      } else if (cameraMode === 'follow') {
+        camera.position.set(carStartX - 7.5, 2.75, 2.6);
+        camera.lookAt(carStartX + 4.0, 1.1, 0);
+      } else if (cameraMode === 'orbit' && !orbitUserInteracted) {
+        camera.position.set(wallX - 4.5, 5.2, 13.5);
+        orbitControls.target.set(wallX - 0.5, 1.1, 0);
+        orbitControls.update();
+      }
+
+      syncVisualsAndCameras(1.0);
+    }
+
+    // =========================================================================
+    // 12. UI WIRING (PLAYBACK, CAMERA SWITCHER & SETTINGS PANEL)
+    // =========================================================================
+    const SETTING_KEYS = Object.keys(MANDATORY_DEFAULTS);
+
+    function writeSettingsToInputs(cfg) {
+      for (const key of SETTING_KEYS) {
+        const el = document.getElementById(`inp-${key}`);
+        if (el) el.value = String(cfg[key]);
+      }
+    }
+
+    function readSettingsFromInputs() {
+      const next = {};
+      for (const key of SETTING_KEYS) {
+        const el = document.getElementById(`inp-${key}`);
+        const raw = el ? parseFloat(el.value) : MANDATORY_DEFAULTS[key];
+        const min = el && el.min !== '' ? parseFloat(el.min) : -Infinity;
+        const max = el && el.max !== '' ? parseFloat(el.max) : Infinity;
+        const val = Number.isFinite(raw) ? Math.min(max, Math.max(min, raw)) : MANDATORY_DEFAULTS[key];
+        next[key] = val;
+        if (el) el.value = String(val);
+      }
+      next.wallCols = Math.round(next.wallCols);
+      next.wallRows = Math.round(next.wallRows);
+      next.wallDepth = Math.round(next.wallDepth);
+      return next;
+    }
+
+    // Play / Pause
+    const playPauseBtn = document.getElementById('btn-play-pause');
+    function setPlayingState(playing) {
+      isPlaying = playing;
+      playPauseBtn.textContent = isPlaying ? 'Pause' : 'Play';
+      playPauseBtn.classList.toggle('btn-primary', isPlaying);
+      playPauseBtn.classList.toggle('btn-action', !isPlaying);
+    }
+
+    playPauseBtn.addEventListener('click', () => {
+      setPlayingState(!isPlaying);
+    });
+
+    // Spacebar toggles pause unless a number input is focused
+    window.addEventListener('keydown', (e) => {
+      if (e.code === 'Space') {
+        const activeEl = document.activeElement;
+        if (activeEl && activeEl.tagName === 'INPUT') return;
+        e.preventDefault();
+        setPlayingState(!isPlaying);
+      }
+    });
+
+    // Replay & Apply (both read the live controls and rebuild the next run)
+    function applyAndReplay() {
+      activeSettings = readSettingsFromInputs();
+      rebuildSimulation();
+      setPlayingState(true);
+    }
+
+    document.getElementById('btn-replay').addEventListener('click', applyAndReplay);
+    document.getElementById('btn-apply-settings').addEventListener('click', applyAndReplay);
+
+    document.getElementById('btn-reset-defaults').addEventListener('click', () => {
+      activeSettings = { ...MANDATORY_DEFAULTS };
+      writeSettingsToInputs(activeSettings);
+      rebuildSimulation();
+      setPlayingState(true);
+    });
+
+    // Simulation speed switcher (0.25x, 0.5x, 1x, 2x)
+    const speedButtons = document.querySelectorAll('#speed-switcher .btn');
+    speedButtons.forEach((btn) => {
+      btn.addEventListener('click', () => {
+        simSpeed = parseFloat(btn.dataset.speed);
+        speedButtons.forEach((b) => b.classList.toggle('active', b === btn));
+      });
+    });
+
+    // Camera view switcher (Impact, Follow, Top, Orbit)
+    const camButtons = document.querySelectorAll('#camera-switcher .btn');
+    camButtons.forEach((btn) => {
+      btn.addEventListener('click', () => {
+        const nextCam = btn.dataset.cam;
+        if (nextCam === 'orbit' && cameraMode !== 'orbit') {
+          orbitUserInteracted = false;
+          camera.position.set(wallX - 4.5, 5.2, 13.5);
+          orbitControls.target.set(wallX - 0.5, 1.1, 0);
+        }
+        cameraMode = nextCam;
+        camButtons.forEach((b) => b.classList.toggle('active', b === btn));
+        syncVisualsAndCameras(1.0);
+      });
+    });
+
+    // Settings drawer toggle
+    const settingsPanel = document.getElementById('settings-panel');
+    document.getElementById('btn-toggle-settings').addEventListener('click', () => {
+      settingsPanel.classList.toggle('collapsed');
+    });
+    document.getElementById('btn-close-settings').addEventListener('click', () => {
+      settingsPanel.classList.add('collapsed');
+    });
+
+    // Window resize handler
+    window.addEventListener('resize', () => {
+      camera.aspect = window.innerWidth / window.innerHeight;
+      camera.updateProjectionMatrix();
+      renderer.setSize(window.innerWidth, window.innerHeight);
+    });
+
+    // =========================================================================
+    // 13. MAIN ANIMATION LOOP (FIXED TIMESTEP + INTERPOLATED RENDER)
+    // =========================================================================
+    writeSettingsToInputs(MANDATORY_DEFAULTS);
+    activeSettings = { ...MANDATORY_DEFAULTS };
+    rebuildSimulation();
+
+    let lastFrameTime = performance.now();
+
+    function animate(now) {
+      requestAnimationFrame(animate);
+
+      const rawDt = Math.min(0.05, Math.max(0, (now - lastFrameTime) / 1000));
+      lastFrameTime = now;
+
+      if (isPlaying) {
+        simAccumulator += rawDt * simSpeed;
+        const maxSteps = 10;
+        let steps = 0;
+        while (simAccumulator >= FIXED_DT && steps < maxSteps) {
+          stepPhysics(FIXED_DT);
+          simAccumulator -= FIXED_DT;
+          steps++;
+        }
+        if (steps === maxSteps) {
+          simAccumulator = 0;
+        }
+      }
+
+      const alpha = isPlaying ? Math.min(1.0, simAccumulator / FIXED_DT) : 1.0;
+      syncVisualsAndCameras(alpha);
+      renderer.render(scene, camera);
+    }
+
+    requestAnimationFrame(animate);
+  </script>
+</body>
+</html>
